DROP TABLE IF EXISTS `his_department`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `his_department` (
  `dept_id` bigint NOT NULL AUTO_INCREMENT COMMENT '科室ID',
  `parent_id` bigint DEFAULT NULL COMMENT '上级科室',
  `dept_name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '科室名称',
  `dept_code` varchar(30) COLLATE utf8mb4_general_ci NOT NULL COMMENT '科室编码',
  `dept_type` char(1) COLLATE utf8mb4_general_ci NOT NULL COMMENT '科室类型',
  `location` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '位置',
  `phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系电话',
  `intro` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '科室简介',
  `order_num` int DEFAULT NULL COMMENT '排序',
  `status` char(1) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '状态',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='科室表';
/*!40101 SET character_set_client = @saved_cs_client */;

